using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Windows.Forms;using System.Xml;
namespace BeamScheduleFormatter {
partial class ProgramOfWorksForm {
 readonly Dictionary<string,SteelProfile> projectSteelProfiles=new Dictionary<string,SteelProfile>(StringComparer.Ordinal);
 SteelProfile FindSteelProfile(string name){SteelProfile profile;return projectSteelProfiles.TryGetValue(name,out profile)?profile:SteelCatalog.Find(name);}
 void WriteSteelProfiles(XmlElement root){root.SetAttribute("appVersion",Engine.Version);var catalog=root.OwnerDocument.CreateElement("SteelProfileSnapshot");root.AppendChild(catalog);var names=steelDemands.Select(d=>d.Specification.Split(new[]{" | "},StringSplitOptions.None)[0]).Distinct();foreach(string name in names){var profile=FindSteelProfile(name);if(profile==null)continue;var row=root.OwnerDocument.CreateElement("Profile");row.SetAttribute("name",profile.Name);row.SetAttribute("kind",profile.Kind);row.SetAttribute("source",profile.Source);row.SetAttribute("H",profile.H.ToString("R",CultureInfo.InvariantCulture));row.SetAttribute("B",profile.B.ToString("R",CultureInfo.InvariantCulture));row.SetAttribute("lip",profile.Lip.ToString("R",CultureInfo.InvariantCulture));row.SetAttribute("t",profile.T.ToString("R",CultureInfo.InvariantCulture));row.SetAttribute("kgm",profile.KgM.ToString("R",CultureInfo.InvariantCulture));catalog.AppendChild(row);}}
 void ReadSteelProfiles(XmlElement root){projectSteelProfiles.Clear();var catalog=root["SteelProfileSnapshot"];if(catalog==null)return;foreach(XmlElement row in catalog.SelectNodes("Profile")){Func<string,double> number=key=>{double value;if(!double.TryParse(row.GetAttribute(key),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||double.IsNaN(value)||double.IsInfinity(value)||value<0)throw new Exception("Invalid saved steel profile "+key);return value;};var profile=new SteelProfile{Name=row.GetAttribute("name"),Kind=row.GetAttribute("kind"),Source=row.GetAttribute("source"),H=number("H"),B=number("B"),Lip=number("lip"),T=number("t"),KgM=number("kgm")};if(profile.Name==""||!new[]{"Purlin","Angle bar"}.Contains(profile.Kind)||projectSteelProfiles.ContainsKey(profile.Name))throw new Exception("Invalid/duplicate saved steel profile.");SteelWeight.Positive(profile.H,profile.B,profile.T,profile.KgM);projectSteelProfiles.Add(profile.Name,profile);var grid=profile.Kind=="Purlin"?steelPurlins:steelAngles;var combo=(DataGridViewComboBoxColumn)grid.Columns[2];if(!combo.Items.Contains(profile.Name))combo.Items.Add(profile.Name);if(profile.Kind=="Angle bar"){var fascia=(DataGridViewComboBoxColumn)fasciaFrame.Columns[3];if(!fascia.Items.Contains(profile.Name))fascia.Items.Add(profile.Name);}}}
}
}
